    public sealed class TestPanel:UIPanel,IUiGeneratedBindings
    {
        internal static bool MissingGeneratedBinding;
        public Result ValidateGeneratedBindings()=>MissingGeneratedBinding?Result.Failure(new FrameworkError(ErrorKind.Integrity,"ui.binding.missing")):Result.Success();
        internal static TestPanel LatestPanel;internal static IAsyncCleanup ExtraCleanup;internal static bool CancelReentrant;internal static int Opens,Closes,Clicks,OpenFailures,CloseFailures;internal static bool ThrowOpen,ThrowClose,RequestCloseOnOpen,CancelThrows;
        internal static UniTaskCompletionSource<Result> OpenGate,CloseGate;internal static IScope LatestView;internal static UiService Service;internal static IScope Owner;
        public override async UniTask<Result> OnOpenAsync(IScope view,OperationContext operation)
        {
            Opens++;LatestView=view;LatestPanel=this;if(ExtraCleanup!=null)Assert.IsTrue(view.Cleanup.Register(ExtraCleanup).IsSuccess);if(CancelReentrant)operation.Cancellation.Register(()=>Service.CloseAsync<TestPanel>(Owner,OperationContext.Unlimited()).Forget());if(ThrowOpen)throw new Exception("open");
            var button=GetComponent<Button>();Assert.IsTrue(UiSubscription.Bind(view,"button",()=>button.onClick.AddListener(Clicked),()=>button.onClick.RemoveListener(Clicked)).IsSuccess);
            if(CancelThrows)operation.Cancellation.Register(()=>throw new Exception("cancel callback"));
            if(RequestCloseOnOpen)Service.CloseAsync<TestPanel>(Owner,OperationContext.Unlimited()).Forget();
            if(OpenGate!=null)return await OpenGate.Task;
            return OpenFailures-->0?Result.Failure(new FrameworkError(ErrorKind.Provider,"fake.open")):Result.Success();
        }
        public override async UniTask<Result> OnCloseAsync(CleanupContext cleanup)
        {Closes++;if(ThrowClose)throw new Exception("close");if(CloseGate!=null)return await CloseGate.Task;return CloseFailures-->0?Result.Failure(new FrameworkError(ErrorKind.CleanupFailed,"fake.close")):Result.Success();}
        private void Clicked(){Clicks++;}
        internal static void Reset(){MissingGeneratedBinding=false;Opens=Closes=Clicks=OpenFailures=CloseFailures=0;ThrowOpen=ThrowClose=RequestCloseOnOpen=CancelThrows=false;OpenGate=CloseGate=null;LatestView=null;LatestPanel=null;ExtraCleanup=null;CancelReentrant=false;Service=null;Owner=null;}
    }
    public sealed class UiServiceTests
    {
        static CleanupContext Cleanup=>new CleanupContext(default,Timeout.InfiniteTimeSpan);
        static ResourceKey Key=>new ResourceKey("fake","main","v1","ui/home",typeof(GameObject));
        readonly List<Env> environments=new List<Env>();
        async UniTask<Env> New(PanelMultiplicity multiplicity=PanelMultiplicity.Single,PanelCachePolicy cache=PanelCachePolicy.ReturnToPool,int capacity=8,bool modal=false,bool home=false)
        {var e=new Env(multiplicity,cache,capacity,modal,home);environments.Add(e);await e.Init();return e;}
        sealed class Env
        {
            internal readonly FakeResourceProvider Provider=new FakeResourceProvider();internal readonly Scope Owner=new Scope("owner");internal readonly List<Scope> Others=new List<Scope>();
            internal readonly ResourceWorkScheduler Scheduler=new ResourceWorkScheduler(new ResourceScheduleBudget(4,4,4,TimeSpan.FromSeconds(1)));
            internal readonly AssetsService Assets;internal readonly GameObjectPool Pool;internal readonly UiService Ui;internal readonly GameContext Context;
            internal readonly GameObject Prefab,Root,Mask;internal bool Loads=true,Releases=true;internal GameServices Access;
            internal Env(PanelMultiplicity multiplicity,PanelCachePolicy cache,int capacity,bool modal,bool home)
            {
                TestPanel.Reset();Prefab=new GameObject("ui-template",typeof(RectTransform),typeof(CanvasRenderer),typeof(Image),typeof(Button),typeof(CanvasGroup));Prefab.SetActive(false);
                if(home)Prefab.AddComponent<HomeView>();else Prefab.AddComponent<TestPanel>();
                Root=new GameObject("authored-ui-root",typeof(RectTransform),typeof(Canvas));Mask=new GameObject("authored-modal-mask",typeof(RectTransform),typeof(CanvasRenderer),typeof(Image));Mask.transform.SetParent(Root.transform,false);Mask.SetActive(false);
                Assets=new AssetsService(Provider,"main","v1",Cleanup,scheduler:Scheduler,schedulerModuleId:Scheduler.Id);
                Pool=new GameObjectPool(Assets,Scheduler,new PoolCapacity(16,8),Cleanup);
                var definition=home?PanelRegistration.For<HomeView>(Key,0,modal,multiplicity,cache):PanelRegistration.For<TestPanel>(Key,0,modal,multiplicity,cache);
                Ui=new UiService(new PooledPanelSource(Pool),new[]{definition},new[]{new UiLayerHost(0,Root.transform,Mask)},Cleanup,capacity);
                TestPanel.Service=Ui;TestPanel.Owner=Owner;
                Context=new GameContext(new[]{new ModuleRegistration(Ui.Id,Ui.Dependencies,()=>Ui,typeof(IUiService)),new ModuleRegistration(Pool.Id,Pool.Dependencies,()=>Pool,typeof(IPoolService<GameObject>)),new ModuleRegistration(Assets.Id,Assets.Dependencies,()=>Assets,typeof(IAssetsService)),new ModuleRegistration(Scheduler.Id,Scheduler.Dependencies,()=>Scheduler,typeof(IResourceWorkScheduler))},Cleanup);Access=new GameServices(Context);
            }
            internal async UniTask Init(){Assert.IsTrue((await Context.StartAsync(OperationContext.Unlimited())).IsSuccess);}
            internal Scope Other(){var s=new Scope("other/"+Others.Count);Others.Add(s);return s;}
            internal void Step(){Scheduler.Tick();Pool.PollDestroyed();for(var i=0;i<Provider.AssetStartCount;i++){var load=Provider.AssetAt<GameObject>(i);if(Loads&&load.Operation.State==BackendState.Running)load.Succeed(Prefab);if(Releases)load.Asset?.ReleaseAttempt?.Complete(Result<Unit>.Success(default));}}
            internal async UniTask<T> Pump<T>(UniTask<T> task){for(var i=0;task.Status==UniTaskStatus.Pending&&i<600;i++){Step();await UniTask.Yield();}Assert.AreNotEqual(UniTaskStatus.Pending,task.Status,"UI did not drain");return await task;}
            internal async UniTask Frames(int count=4){for(var i=0;i<count;i++){Step();await UniTask.Yield();}}
            internal async UniTask<IUiSession<TestPanel>> Open(IScope owner=null){var result=await Pump(Ui.OpenAsync<TestPanel>(owner??Owner,OperationContext.Unlimited()));Assert.IsTrue(result.IsSuccess,result.IsSuccess?"":result.Error.Code);return result.Value;}
            internal async UniTask Finish()
            {
                Loads=Releases=true;TestPanel.ThrowClose=false;TestPanel.CloseFailures=0;TestPanel.OpenGate?.TrySetResult(Result.Success());TestPanel.CloseGate?.TrySetResult(Result.Success());
                foreach(var owner in Others.Concat(new[]{Owner})){await Pump(owner.CloseAsync(Cleanup));await Pump(owner.RetryFailedAsync(Cleanup));}
                await Pump(Ui.RetryCleanupAsync(OperationContext.Unlimited()));
                var result=await Pump(Context.CloseAsync(OperationContext.Unlimited()));if(!result.IsSuccess)result=await Pump(Context.CloseAsync(OperationContext.Unlimited()));
                Assert.IsTrue(result.IsSuccess);Assert.AreEqual(0,Ui.SessionCount);Assert.AreEqual(0,Ui.RetainedSlotCount);Assert.AreEqual(0,Assets.RetainedEntryCount);Assert.AreEqual(0,Pool.BucketCount);
                Object.DestroyImmediate(Prefab);Object.DestroyImmediate(Root);TestPanel.Reset();
            }
        }
        sealed class FailOnce:IAsyncCleanup
        {public string Id=>"view-fault";internal int Calls;public UniTask<Result> CleanupAsync(CleanupContext c){Calls++;return UniTask.FromResult(Calls==1?Result.Failure(new FrameworkError(ErrorKind.CleanupFailed,"test.view.cleanup")):Result.Success());}}
        [UnityTearDown] public IEnumerator TearDown()=>UniTask.ToCoroutine(async()=>{foreach(var e in environments)await e.Finish();environments.Clear();});
        [UnityTest] public IEnumerator TenConcurrentSingletonOpensCreateOneInstance()=>UniTask.ToCoroutine(async()=>{var e=await New();var tasks=new List<UniTask<Result<IUiSession<TestPanel>>>>();for(int i=0;i<10;i++)tasks.Add(e.Ui.OpenAsync<TestPanel>(e.Owner,OperationContext.Unlimited()));var ids=new HashSet<string>();foreach(var task in tasks){var result=await e.Pump(task);Assert.IsTrue(result.IsSuccess);ids.Add(result.Value.Id);}Assert.AreEqual(1,ids.Count);Assert.AreEqual(1,e.Pool.CreatedCount);Assert.AreEqual(1,TestPanel.Opens);Assert.AreEqual(1,e.Ui.SessionCount);});
        [UnityTest] public IEnumerator MultiplePanelsHaveIndependentSessions()=>UniTask.ToCoroutine(async()=>{var e=await New(PanelMultiplicity.Multiple);var a=await e.Open();var b=await e.Open();Assert.AreNotEqual(a.Id,b.Id);Assert.AreNotSame(a.Panel,b.Panel);Assert.AreNotSame(a.ViewScope,b.ViewScope);Assert.AreEqual(2,e.Pool.ActiveCount);await e.Pump(a.CloseAsync(OperationContext.Unlimited()));Assert.AreEqual(UiSessionState.Open,b.State);});
        [UnityTest] public IEnumerator OtherOwnerCannotTakeActiveSingleton()=>UniTask.ToCoroutine(async()=>{var e=await New();await e.Open();var result=await e.Pump(e.Ui.OpenAsync<TestPanel>(e.Other(),OperationContext.Unlimited()));Assert.AreEqual("ui.singleton.owned_or_closing",result.Error.Code);Assert.AreEqual(1,e.Pool.CreatedCount);});
        [UnityTest] public IEnumerator OneCanceledWaiterDoesNotCancelRemainingWaiter()=>UniTask.ToCoroutine(async()=>{var e=await New();e.Loads=false;using(var cancel=new CancellationTokenSource()){var a=e.Ui.OpenAsync<TestPanel>(e.Owner,OperationContext.Unlimited(cancel.Token));var b=e.Ui.OpenAsync<TestPanel>(e.Owner,OperationContext.Unlimited());cancel.Cancel();Assert.AreEqual(ErrorKind.Canceled,(await e.Pump(a)).Error.Kind);e.Loads=true;Assert.IsTrue((await e.Pump(b)).IsSuccess);Assert.AreEqual(1,TestPanel.Opens);}});
        [UnityTest] public IEnumerator AllCanceledWaitersDrainLateLoad()=>UniTask.ToCoroutine(async()=>{var e=await New();e.Loads=false;using(var cancel=new CancellationTokenSource()){var a=e.Ui.OpenAsync<TestPanel>(e.Owner,OperationContext.Unlimited(cancel.Token));await e.Frames();cancel.Cancel();Assert.AreEqual(ErrorKind.Canceled,(await e.Pump(a)).Error.Kind);Assert.Greater(e.Ui.RetainedSlotCount,0);e.Loads=true;await e.Frames(12);Assert.AreEqual(0,e.Ui.SessionCount);Assert.AreEqual(0,e.Ui.RetainedSlotCount);Assert.AreEqual(0,TestPanel.Opens);}});
        [UnityTest] public IEnumerator CloseDuringLoadPreventsLatePanelCommit()=>UniTask.ToCoroutine(async()=>{var e=await New();e.Loads=false;var opened=e.Ui.OpenAsync<TestPanel>(e.Owner,OperationContext.Unlimited());await e.Frames();var close=e.Ui.CloseAsync<TestPanel>(e.Owner,OperationContext.Unlimited());await e.Frames();Assert.AreEqual(UniTaskStatus.Pending,close.Status);e.Loads=true;Assert.IsTrue((await e.Pump(close)).IsSuccess);Assert.IsFalse((await e.Pump(opened)).IsSuccess);Assert.AreEqual(0,e.Ui.SessionCount);});
        [UnityTest] public IEnumerator OwnerCloseDuringLoadOwnsActualDrain()=>UniTask.ToCoroutine(async()=>{var e=await New();e.Loads=false;var open=e.Ui.OpenAsync<TestPanel>(e.Owner,OperationContext.Unlimited());await e.Frames();var close=e.Owner.CloseAsync(Cleanup);await e.Frames();Assert.AreEqual(UniTaskStatus.Pending,close.Status);e.Loads=true;Assert.IsTrue((await e.Pump(close)).IsFullyDrained);Assert.IsFalse((await e.Pump(open)).IsSuccess);Assert.AreEqual(0,e.Ui.RetainedSlotCount);});
        [UnityTest] public IEnumerator CloseDuringOpenHookWaitsForActualHook()=>UniTask.ToCoroutine(async()=>{var e=await New();TestPanel.OpenGate=new UniTaskCompletionSource<Result>();var open=e.Ui.OpenAsync<TestPanel>(e.Owner,OperationContext.Unlimited());await e.Frames(10);var close=e.Ui.CloseAsync<TestPanel>(e.Owner,OperationContext.Unlimited());await e.Frames();Assert.AreEqual(UniTaskStatus.Pending,close.Status);TestPanel.OpenGate.TrySetResult(Result.Success());Assert.IsTrue((await e.Pump(close)).IsSuccess);Assert.IsFalse((await e.Pump(open)).IsSuccess);});
        [UnityTest] public IEnumerator ContextStopPreventsLateOpenAndDrains()=>UniTask.ToCoroutine(async()=>{var e=await New();TestPanel.OpenGate=new UniTaskCompletionSource<Result>();var open=e.Ui.OpenAsync<TestPanel>(e.Owner,OperationContext.Unlimited());await e.Frames(10);var close=e.Context.CloseAsync(OperationContext.Unlimited());await e.Frames();Assert.AreEqual(UniTaskStatus.Pending,close.Status);TestPanel.OpenGate.TrySetResult(Result.Success());Assert.IsTrue((await e.Pump(close)).IsSuccess);Assert.IsFalse((await e.Pump(open)).IsSuccess);});
        [UnityTest] public IEnumerator ZeroTimeoutStartsNoRent()=>UniTask.ToCoroutine(async()=>{var e=await New();Assert.AreEqual(ErrorKind.Timeout,(await e.Ui.OpenAsync<TestPanel>(e.Owner,default)).Error.Kind);Assert.AreEqual(0,e.Provider.AssetStartCount);Assert.AreEqual(0,e.Ui.SessionCount);});
        [UnityTest] public IEnumerator PreCanceledRequestStartsNoRent()=>UniTask.ToCoroutine(async()=>{var e=await New();using(var cancel=new CancellationTokenSource()){cancel.Cancel();Assert.AreEqual(ErrorKind.Canceled,(await e.Ui.OpenAsync<TestPanel>(e.Owner,OperationContext.Unlimited(cancel.Token))).Error.Kind);}Assert.AreEqual(0,e.Ui.RetainedSlotCount);});
        [UnityTest] public IEnumerator OpenFailureIsNotCached()=>UniTask.ToCoroutine(async()=>{var e=await New(cache:PanelCachePolicy.RetainInstance);TestPanel.OpenFailures=1;Assert.IsFalse((await e.Pump(e.Ui.OpenAsync<TestPanel>(e.Owner,OperationContext.Unlimited()))).IsSuccess);await e.Frames();Assert.AreEqual(0,e.Ui.CachedCount);Assert.AreEqual(0,e.Ui.SessionCount);});
        [UnityTest] public IEnumerator OpenExceptionDrainsBindingsAndRent()=>UniTask.ToCoroutine(async()=>{var e=await New();TestPanel.ThrowOpen=true;var result=await e.Pump(e.Ui.OpenAsync<TestPanel>(e.Owner,OperationContext.Unlimited()));Assert.AreEqual(ErrorKind.Unexpected,result.Error.Kind);await e.Frames();Assert.AreEqual(0,e.Ui.SessionCount);});
        [UnityTest] public IEnumerator CloseFailureRequiresExplicitRetry()=>UniTask.ToCoroutine(async()=>{var e=await New();var view=await e.Open();TestPanel.CloseFailures=1;Assert.IsFalse((await e.Pump(view.CloseAsync(OperationContext.Unlimited()))).IsSuccess);Assert.AreEqual(UiSessionState.CleanupFailed,view.State);Assert.AreEqual(1,e.Pool.ActiveCount);Assert.IsFalse((await e.Pump(view.CloseAsync(OperationContext.Unlimited()))).IsSuccess);Assert.AreEqual(1,TestPanel.Closes);Assert.IsTrue((await e.Pump(view.RetryCloseAsync(OperationContext.Unlimited()))).IsSuccess);Assert.AreEqual(2,TestPanel.Closes);});
        [UnityTest] public IEnumerator CloseExceptionIsRetryable()=>UniTask.ToCoroutine(async()=>{var e=await New();var view=await e.Open();TestPanel.ThrowClose=true;Assert.IsFalse((await e.Pump(view.CloseAsync(OperationContext.Unlimited()))).IsSuccess);TestPanel.ThrowClose=false;Assert.IsTrue((await e.Pump(e.Ui.RetryCleanupAsync(OperationContext.Unlimited()))).IsSuccess);Assert.AreEqual(UiSessionState.Closed,view.State);});
        [UnityTest] public IEnumerator ConcurrentClosesInvokeHookOnce()=>UniTask.ToCoroutine(async()=>{var e=await New();var view=await e.Open();TestPanel.CloseGate=new UniTaskCompletionSource<Result>();var a=view.CloseAsync(OperationContext.Unlimited());var b=view.CloseAsync(OperationContext.Unlimited());Assert.AreEqual(1,TestPanel.Closes);TestPanel.CloseGate.TrySetResult(Result.Success());Assert.IsTrue((await e.Pump(a)).IsSuccess);Assert.IsTrue((await e.Pump(b)).IsSuccess);Assert.AreEqual(1,TestPanel.Closes);});
        [UnityTest] public IEnumerator CloseObserverCancellationDoesNotAbandonCleanup()=>UniTask.ToCoroutine(async()=>{var e=await New();var view=await e.Open();TestPanel.CloseGate=new UniTaskCompletionSource<Result>();using(var cancel=new CancellationTokenSource()){var task=view.CloseAsync(OperationContext.Unlimited(cancel.Token));cancel.Cancel();Assert.AreEqual(ErrorKind.Canceled,(await e.Pump(task)).Error.Kind);Assert.AreEqual(1,e.Pool.ActiveCount);TestPanel.CloseGate.TrySetResult(Result.Success());Assert.IsTrue((await e.Pump(view.CloseAsync(OperationContext.Unlimited()))).IsSuccess);}});
        [UnityTest] public IEnumerator ClosingSingletonRejectsReopen()=>UniTask.ToCoroutine(async()=>{var e=await New();var view=await e.Open();TestPanel.CloseGate=new UniTaskCompletionSource<Result>();var close=view.CloseAsync(OperationContext.Unlimited());var result=await e.Pump(e.Ui.OpenAsync<TestPanel>(e.Owner,OperationContext.Unlimited()));Assert.AreEqual(ErrorKind.InvalidState,result.Error.Kind);TestPanel.CloseGate.TrySetResult(Result.Success());await e.Pump(close);});
        [UnityTest] public IEnumerator CachedPanelReopensWithNewViewScope()=>UniTask.ToCoroutine(async()=>{var e=await New(cache:PanelCachePolicy.RetainInstance);var a=await e.Open();var go=a.Panel.gameObject;var scope=a.ViewScope;await e.Pump(a.CloseAsync(OperationContext.Unlimited()));Assert.IsNull(a.Panel);Assert.AreEqual(1,e.Ui.CachedCount);Assert.IsFalse(go.activeSelf);var b=await e.Open();Assert.AreSame(go,b.Panel.gameObject);Assert.AreNotEqual(a.Id,b.Id);Assert.AreNotSame(scope,b.ViewScope);Assert.AreEqual(ScopeState.Closed,scope.State);Assert.AreEqual(1,e.Pool.CreatedCount);});
        [UnityTest] public IEnumerator HundredCachedCyclesDoNotAccumulateButtonListeners()=>UniTask.ToCoroutine(async()=>{var e=await New(cache:PanelCachePolicy.RetainInstance);for(int i=0;i<100;i++){var view=await e.Open();var button=view.Panel.GetComponent<Button>();button.onClick.Invoke();Assert.AreEqual(i+1,TestPanel.Clicks);await e.Pump(view.CloseAsync(OperationContext.Unlimited()));button.onClick.Invoke();Assert.AreEqual(i+1,TestPanel.Clicks);}Assert.AreEqual(1,e.Pool.CreatedCount);Assert.AreEqual(100,TestPanel.Opens);Assert.AreEqual(100,TestPanel.Closes);Assert.AreEqual(0,e.Ui.SessionCount);Assert.AreEqual(1,e.Ui.CachedCount);});
        [UnityTest] public IEnumerator CacheBudgetReturnsExcessInstancesToPool()=>UniTask.ToCoroutine(async()=>{var e=await New(PanelMultiplicity.Multiple,PanelCachePolicy.RetainInstance,1);var a=await e.Open();var b=await e.Open();await e.Pump(a.CloseAsync(OperationContext.Unlimited()));await e.Pump(b.CloseAsync(OperationContext.Unlimited()));Assert.AreEqual(1,e.Ui.CachedCount);Assert.AreEqual(1,e.Pool.ActiveCount);Assert.AreEqual(1,e.Pool.IdleCount);});
        [UnityTest] public IEnumerator ZeroCacheBudgetReturnsEveryInstance()=>UniTask.ToCoroutine(async()=>{var e=await New(cache:PanelCachePolicy.RetainInstance,capacity:0);var v=await e.Open();await e.Pump(v.CloseAsync(OperationContext.Unlimited()));Assert.AreEqual(0,e.Ui.CachedCount);Assert.AreEqual(0,e.Pool.ActiveCount);});
        [UnityTest] public IEnumerator TrimCachePreservesOpenPanels()=>UniTask.ToCoroutine(async()=>{var e=await New(PanelMultiplicity.Multiple,PanelCachePolicy.RetainInstance);var a=await e.Open();var b=await e.Open();await e.Pump(a.CloseAsync(OperationContext.Unlimited()));Assert.IsTrue((await e.Pump(e.Ui.TrimCacheAsync(OperationContext.Unlimited()))).IsSuccess);Assert.AreEqual(0,e.Ui.CachedCount);Assert.AreEqual(UiSessionState.Open,b.State);Assert.AreEqual(1,e.Pool.ActiveCount);});
        [UnityTest] public IEnumerator OwnerCloseMayRetainCacheButClosesViewBindings()=>UniTask.ToCoroutine(async()=>{var e=await New(cache:PanelCachePolicy.RetainInstance);var v=await e.Open();var button=v.Panel.GetComponent<Button>();Assert.IsTrue((await e.Pump(e.Owner.CloseAsync(Cleanup))).IsFullyDrained);button.onClick.Invoke();Assert.AreEqual(0,TestPanel.Clicks);Assert.AreEqual(1,e.Ui.CachedCount);Assert.AreEqual(ScopeState.Closed,v.ViewScope.State);});
        [UnityTest] public IEnumerator CachedSlotCanTransferToANewOwnerAfterClose()=>UniTask.ToCoroutine(async()=>{var e=await New(cache:PanelCachePolicy.RetainInstance);var a=await e.Open();var obj=a.Panel.gameObject;await e.Pump(a.CloseAsync(OperationContext.Unlimited()));var b=await e.Open(e.Other());Assert.AreSame(obj,b.Panel.gameObject);await e.Pump(e.Owner.CloseAsync(Cleanup));Assert.AreEqual(UiSessionState.Open,b.State);});
        [UnityTest] public IEnumerator DestroyedOpenPanelCanStillClose()=>UniTask.ToCoroutine(async()=>{var e=await New();var v=await e.Open();Object.Destroy(v.Panel.gameObject);await e.Frames();Assert.IsTrue((await e.Pump(v.CloseAsync(OperationContext.Unlimited()))).IsSuccess);Assert.AreEqual(0,e.Ui.RetainedSlotCount);});
        [UnityTest] public IEnumerator DestroyedCachedPanelDoesNotCommitReopen()=>UniTask.ToCoroutine(async()=>{var e=await New(cache:PanelCachePolicy.RetainInstance);var v=await e.Open();var obj=v.Panel.gameObject;await e.Pump(v.CloseAsync(OperationContext.Unlimited()));Object.Destroy(obj);await e.Frames();var result=await e.Pump(e.Ui.OpenAsync<TestPanel>(e.Owner,OperationContext.Unlimited()));Assert.IsFalse(result.IsSuccess);await e.Frames();Assert.AreEqual(0,e.Ui.SessionCount);});
        [UnityTest] public IEnumerator ModalMaskTracksVisibleSessionAndStopsOnClose()=>UniTask.ToCoroutine(async()=>{var e=await New(modal:true);var v=await e.Open();Assert.IsTrue(e.Mask.activeSelf);Assert.Less(e.Mask.transform.GetSiblingIndex(),v.Panel.transform.GetSiblingIndex());await e.Pump(v.CloseAsync(OperationContext.Unlimited()));Assert.IsFalse(e.Mask.activeSelf);});
