        [UnityTest] public IEnumerator CachedAnimatorResetsBeforeNewOpenSession()=>UniTask.ToCoroutine(async()=>{
#if UNITY_EDITOR
            var e=await New(cache:PanelCachePolicy.RetainInstance);var controller=new UnityEditor.Animations.AnimatorController();controller.AddLayer("Base");controller.AddParameter("Visible",AnimatorControllerParameterType.Bool);var state=controller.layers[0].stateMachine.AddState("Idle");controller.layers[0].stateMachine.defaultState=state;
            e.Prefab.AddComponent<Animator>().runtimeAnimatorController=controller;
            try{var first=await e.Open();var driver=AnimatorPresentation.Create(first.Panel.GetComponent<Animator>(),first.ViewScope,"animation").Value;Assert.IsTrue(driver.SetVisible(true).IsSuccess);await e.Pump(first.CloseAsync(OperationContext.Unlimited()));var second=await e.Open();Assert.IsFalse(second.Panel.GetComponent<Animator>().GetBool("Visible"));Assert.AreEqual(1,e.Pool.CreatedCount);await e.Pump(second.CloseAsync(OperationContext.Unlimited()));await e.Pump(e.Ui.TrimCacheAsync(OperationContext.Unlimited()));}
            finally{Object.DestroyImmediate(state);Object.DestroyImmediate(controller.layers[0].stateMachine);Object.DestroyImmediate(controller);}
#else
            Assert.Fail("This fixture needs an Editor-created AnimatorController; no Player claim.");await UniTask.Yield();
#endif
        });
        [UnityTest] public IEnumerator AnimationWaitObservesActualNonLoopingCompletionAtZeroTimeScale()=>AnimationCase(0);
        [UnityTest] public IEnumerator AnimationZeroDeadlineDoesNotChangeVisibility()=>AnimationCase(1);
        [UnityTest] public IEnumerator AnimationScopeCloseEndsPendingObservation()=>AnimationCase(2);
        [UnityTest] public IEnumerator AnimationNewCommandSupersedesOldObservation()=>AnimationCase(3);
        IEnumerator AnimationCase(int mode)=>UniTask.ToCoroutine(async()=>{
#if UNITY_EDITOR
            var root=new GameObject("animation-fixture",typeof(RectTransform),typeof(CanvasGroup),typeof(Animator));var owner=new Scope("animation-owner");
            var controller=new UnityEditor.Animations.AnimatorController();controller.AddLayer("Base");controller.AddParameter("Visible",AnimatorControllerParameterType.Bool);
            var machine=controller.layers[0].stateMachine;var idle=machine.AddState("Idle");var open=machine.AddState("Open");machine.defaultState=idle;
            var clip=new AnimationClip();clip.SetCurve("",typeof(CanvasGroup),"m_Alpha",AnimationCurve.Linear(0,0,.05f,1));open.motion=clip;
            var transition=idle.AddTransition(open);transition.hasExitTime=false;transition.duration=0;transition.AddCondition(UnityEditor.Animations.AnimatorConditionMode.If,0,"Visible");
            var animator=root.GetComponent<Animator>();animator.runtimeAnimatorController=controller;animator.Rebind();animator.Update(0);
            var driver=AnimatorPresentation.Create(animator,owner,"anim").Value;var scale=Time.timeScale;
            try{
                if(mode==0){Time.timeScale=0;var task=driver.PlayAsync(true,Animator.StringToHash("Base.Open"),0,new OperationContext(default,TimeSpan.FromSeconds(3)));Assert.AreEqual(UniTaskStatus.Pending,task.Status);var result=await task;Assert.IsTrue(result.IsSuccess,result.IsSuccess?"":result.Error.Code);Assert.GreaterOrEqual(animator.GetCurrentAnimatorStateInfo(0).normalizedTime,1);}
                if(mode==1){Assert.AreEqual(ErrorKind.Timeout,(await driver.PlayAsync(true,Animator.StringToHash("Base.Open"),0,default)).Error.Kind);Assert.IsFalse(animator.GetBool("Visible"));}
                if(mode==2){var task=driver.PlayAsync(false,Animator.StringToHash("Base.Open"),0,OperationContext.Unlimited());await owner.CloseAsync(Cleanup);Assert.AreEqual(ErrorKind.Canceled,(await task).Error.Kind);Assert.IsFalse(animator.enabled);}
                if(mode==3){var task=driver.PlayAsync(false,Animator.StringToHash("Base.Open"),0,OperationContext.Unlimited());driver.SetVisible(true);Assert.AreEqual(ErrorKind.Canceled,(await task).Error.Kind);}
            }finally{Time.timeScale=scale;await owner.CloseAsync(Cleanup);Object.DestroyImmediate(root);Object.DestroyImmediate(transition);Object.DestroyImmediate(idle);Object.DestroyImmediate(open);Object.DestroyImmediate(machine);Object.DestroyImmediate(controller);Object.DestroyImmediate(clip);}
#else
            Assert.Fail("Editor controller fixture only.");await UniTask.Yield();
#endif
        });
